def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Remove duplicates while preserving order
    seen = set()
    unique_classes = []
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            unique_classes.append(cls)

    # Remove any class that is a subclass of another class in the list
    # We want to keep only the most specific (leaf) classes
    # Actually, we want to remove classes that are superclasses of other classes in the list
    # Because if A is a subclass of B, then A already inherits from B, so B is redundant

    minimal = []
    for i, cls in enumerate(unique_classes):
        # Check if cls is a superclass of any other class in unique_classes
        is_redundant = False
        for j, other in enumerate(unique_classes):
            if i == j:
                continue
            # If other is a subclass of cls (and other is not cls itself), then cls is redundant
            # because other already inherits from cls
            if issubclass(other, cls) and other is not cls:
                is_redundant = True
                break
        if not is_redundant:
            minimal.append(cls)

    return minimal

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    if all:
        return self._all_attributes
    else:
        return self._attributes

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if all:
        return list(self._attributes.keys())
    else:
        return [name for name, attr in self._attributes.items() if not attr._private]

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    for item in sequence:
        if isinstance(item, (list, tuple)):
            _normalizeargs(item, output)
        else:
            output.append(item)

    return output

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self._context = {}
    if self._initial_value is not None:
        self._bins = {key: self._initial_value for key in self._keys}
    else:
        self._bins = self._make_bins()

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not hasattr(self, 'err_indices'):
        return []
    if not hasattr(self, 'coord_names'):
        return []
    if coord_name not in self.coord_names:
        return []
    coord_idx = self.coord_names.index(coord_name)
    return self.err_indices[coord_idx]

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # We need to check if seq is a FillRequest element or contains at least one such,
    # and it is not a Source sequence.
    # Since we don't have the actual classes, we'll assume they exist in the environment.
    # We'll use duck typing or isinstance checks.

    # First, check if it's a Source sequence - if so, return False
    try:
        from .source import Source
        if isinstance(seq, Source):
            return False
    except ImportError:
        pass

    # Check if seq is a FillRequest element
    try:
        from .fill_request import FillRequest
        if isinstance(seq, FillRequest):
            return True
    except ImportError:
        pass

    # Check if seq is a sequence that contains at least one FillRequest
    try:
        from .fill_request import FillRequest
        if hasattr(seq, '__iter__') and not isinstance(seq, (str, bytes)):
            for item in seq:
                if isinstance(item, FillRequest):
                    return True
    except ImportError:
        pass

    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        if not hasattr(obj, 'fill') or not hasattr(obj, 'request'):
            return False
        if not callable(obj.fill) or not callable(obj.request):
            return False
        return True
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        run_method = getattr(obj, 'run', None)
        if run_method is None:
            return False
        if not callable(run_method):
            return False
        return True
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        has_fill = hasattr(obj, 'fill') and callable(getattr(obj, 'fill'))
        has_compute = hasattr(obj, 'compute') and callable(getattr(obj, 'compute'))
        return has_fill and has_compute
    except Exception:
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both arguments must be dictionaries")

    result = {}

    for key, value1 in d1.items():
        if key not in d2:
            result[key] = value1
        else:
            value2 = d2[key]
            if isinstance(value1, dict) and isinstance(value2, dict):
                if level == 0:
                    # At level 0, we don't recurse, so if both are dicts, we treat them as different
                    # Actually, level 0 means no recursion, so we should compare directly?
                    # Let's think: level 1 means if key present in both but different values, include.
                    # So level 0 would mean we don't even check? Or level 0 means we stop recursing.
                    # The docstring says "For level 1, if a key is present both in d1 and d2 but has different values, it is included into the difference."
                    # This suggests that for level >= 1, we do the comparison. For level 0, we might not recurse.
                    # Let's assume level 0 means we don't recurse into sub-dicts, so we just compare the dicts directly.
                    if value1 != value2:
                        result[key] = value1
                else:
                    # Recurse
                    new_level = level - 1 if level != -1 else -1
                    diff = difference(value1, value2, new_level)
                    if diff:
                        result[key] = diff
            else:
                if value1 != value2:
                    result[key] = value1

    return result

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    def _generate_default_schema_for_kind(kind):
        """Generate a default observer schema for a given Kubernetes resource kind.

        Args:
            kind (str): The Kubernetes resource kind (e.g., 'Deployment', 'Service', etc.)

        Returns:
            dict: A default observer schema for the given kind
        """
        # Define default schemas for common Kubernetes resource kinds
        default_schemas = {
            'Deployment': {
                'type': 'object',
                'properties': {
                    'status': {
                        'type': 'object',
                        'properties': {
                            'readyReplicas': {'type': 'integer'},
                            'availableReplicas': {'type': 'integer'},
                            'updatedReplicas': {'type': 'integer'},
                            'replicas': {'type': 'integer'}
                        }
                    }
                }
            },
            'StatefulSet': {
                'type': 'object',
                'properties': {
                    'status': {
                        'type': 'object',
                        'properties': {
                            'readyReplicas': {'type': 'integer'},
                            'currentReplicas': {'type': 'integer'},
                            'replicas': {'type': 'integer'}
                        }
                    }
                }
            },
            'DaemonSet': {
                'type': 'object',
                'properties': {
                    'status': {
                        'type': 'object',
                        'properties': {
                            'readyNodes': {'type': 'integer'},
                            'currentNumberScheduled': {'type': 'integer'},
                            'desiredNumberScheduled': {'type': 'integer'}
                        }
                    }
                }
            },
            'Service': {
                'type': 'object',
                'properties': {
                    'spec': {
                        'type': 'object',
                        'properties': {
                            'clusterIP': {'type': 'string'},
                            'type': {'type': 'string'}
                        }
                    }
                }
            },
            'Pod': {
                'type': 'object',
                'properties': {
                    'status': {
                        'type': 'object',
                        'properties': {
                            'phase': {'type': 'string'},
                            'conditions': {'type': 'array'}
                        }
                    }
                }
            },
            'Job': {
                'type': 'object',
                'properties': {
                    'status': {
                        'type': 'object',
                        'properties': {
                            'succeeded': {'type': 'integer'},
                            'failed': {'type': 'integer'},
                            'active': {'type': 'integer'}
                        }
                    }
                }
            },
            'CronJob': {
                'type': 'object',
                'properties': {
                    'status': {
                        'type': 'object',
                        'properties': {
                            'lastScheduleTime': {'type': 'string'},
                            'lastSuccessfulTime': {'type': 'string'}
                        }
                    }
                }
            }
        }

        # Return the specific schema if available, otherwise return a generic one
        if kind in default_schemas:
            return default_schemas[kind]

        # Generic default schema for unknown kinds
        return {
            'type': 'object',
            'properties': {
                'status': {
                    'type': 'object'
                }
            }
        }
    # We need to iterate over the resources in the manifest
    # and for each resource that doesn't have a custom observer schema,
    # generate a default one.

    # The app object should have a spec attribute with a manifest attribute.
    # The manifest is likely a list of Kubernetes resource definitions.
    # Each resource definition might have a 'kind' and 'metadata' with 'name'.
    # The observer schema might be stored in app.spec.observer_schemas or similar.

    # Since we don't have the exact structure of the krake.data.kubernetes.Application object,
    # we'll make reasonable assumptions based on common patterns.

    # Let's assume:
    # - app.spec.manifest is a list of dicts, each representing a Kubernetes resource
    # - Each resource dict has 'kind' and 'metadata' keys
    # - app.spec.observer_schemas is a dict mapping resource identifiers to observer schemas
    # - The resource identifier could be a string like "kind/name" or a tuple

    # We'll generate a default observer schema for each resource in the manifest
    # that doesn't already have one in app.spec.observer_schemas.

    # First, let's check if the necessary attributes exist
    if not hasattr(app, 'spec'):
        return

    spec = app.spec

    if not hasattr(spec, 'manifest'):
        return

    manifest = spec.manifest

    if not manifest:
        return

    # Initialize observer_schemas if it doesn't exist
    if not hasattr(spec, 'observer_schemas'):
        spec.observer_schemas = {}

    observer_schemas = spec.observer_schemas

    # Iterate over each resource in the manifest
    for resource in manifest:
        if not isinstance(resource, dict):
            continue

        # Extract kind and name
        kind = resource.get('kind')
        metadata = resource.get('metadata', {})
        name = metadata.get('name')

        if not kind or not name:
            continue

        # Create a unique identifier for this resource
        resource_id = f"{kind}/{name}"

        # Check if a custom observer schema already exists for this resource
        if resource_id not in observer_schemas:
            # Generate a default observer schema
            # The default schema should be appropriate for the resource kind
            default_schema = _generate_default_schema_for_kind(kind)
            observer_schemas[resource_id] = default_schema

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not hasattr(self, 'status'):
        return prefix + "unknown"
    return prefix + str(self.status)

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not hasattr(self, 'log') or self.log is None:
        return prefix + "No validation log available."

    if not isinstance(self.log, list):
        return prefix + "Invalid log format."

    if not self.log:
        return prefix + "No validation entries."

    lines = []
    for entry in self.log:
        if isinstance(entry, dict):
            level = entry.get('level', 'INFO')
            message = entry.get('message', '')
            lines.append(f"{level}: {message}")
        else:
            lines.append(str(entry))

    return prefix + "\n".join(lines)

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Collect all digests from manifest files
        manifest_digests = set()
        for file_path in manifest_files:
            try:
                with open(file_path, 'r') as f:
                    for line in f:
                        line = line.strip()
                        if line:
                            manifest_digests.add(line)
            except Exception as e:
                raise ValueError(f"Error reading manifest file {file_path}: {e}")

        # Check that all digests used are present in manifest
        missing_digests = digests_used - manifest_digests
        if missing_digests:
            raise ValueError(f"Digests used but not present in manifest: {missing_digests}")

        # Check that all digests in manifest are used
        unused_digests = manifest_digests - digests_used
        if unused_digests:
            raise ValueError(f"Digests present in manifest but not used: {unused_digests}")

        return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if not isinstance(version, (int, str)):
        raise TypeError("version must be an integer or string")

    # Check if version exists in inventory
    if version not in inventory:
        raise ValueError(f"Version {version} not found in inventory")

    version_data = inventory[version]

    if not isinstance(version_data, dict):
        raise TypeError(f"Version data for {version} must be a dictionary")

    # The version_data should contain a mapping of logical paths to content files
    # We need to handle the case where content_files might be a list or a single value
    logical_path_map = {}

    for logical_path, content_files in version_data.items():
        if not isinstance(logical_path, str):
            raise TypeError(f"Logical path must be a string, got {type(logical_path)}")

        # Convert content_files to a set
        if isinstance(content_files, (list, tuple, set)):
            content_files_set = set(content_files)
        elif isinstance(content_files, str):
            content_files_set = {content_files}
        else:
            content_files_set = {content_files}

        logical_path_map[logical_path] = content_files_set

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("Fixity must be a dictionary")

        # Check that fixity has the required keys
        required_keys = {'files', 'algorithm'}
        if not required_keys.issubset(fixity.keys()):
            raise ValueError(f"Fixity block must contain keys: {required_keys}")

        files = fixity.get('files', [])
        algorithm = fixity.get('algorithm', '')

        if not isinstance(files, list):
            raise ValueError("Fixity 'files' must be a list")

        if not isinstance(algorithm, str) or not algorithm:
            raise ValueError("Fixity 'algorithm' must be a non-empty string")

        # Check that each file entry is valid
        for i, file_entry in enumerate(files):
            if not isinstance(file_entry, dict):
                raise ValueError(f"Fixity file entry at index {i} must be a dictionary")

            # Check required keys in file entry
            file_required_keys = {'path', 'checksum'}
            if not file_required_keys.issubset(file_entry.keys()):
                raise ValueError(f"Fixity file entry at index {i} must contain keys: {file_required_keys}")

            path = file_entry.get('path', '')
            checksum = file_entry.get('checksum', '')

            if not isinstance(path, str) or not path:
                raise ValueError(f"Fixity file entry at index {i} must have a non-empty 'path' string")

            if not isinstance(checksum, str) or not checksum:
                raise ValueError(f"Fixity file entry at index {i} must have a non-empty 'checksum' string")

            # Check that the file is in the manifest
            if path not in manifest_files:
                raise ValueError(f"File '{path}' in fixity block is not listed in the manifest")

        return True

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    try:
        if not os.path.exists(path):
            raise FileNotFoundError(f"Path does not exist: {path}")
        if not os.path.isdir(path):
            raise NotADirectoryError(f"Path is not a directory: {path}")
        files = []
        for entry in os.listdir(path):
            full_path = os.path.join(path, entry)
            if os.path.isfile(full_path):
                files.append(entry)
        return files
    except Exception as e:
        raise e

