def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if style == "pep440":
        # PEP 440 style
        if pieces["distance"] is None:
            # no distance, so it's a release
            return pieces["version"]
        else:
            # distance is not None, so it's a dev version
            return pieces["version"] + ".dev" + str(pieces["distance"])
    elif style == "git-describe":
        # git describe style
        if pieces["distance"] is None:
            return pieces["version"]
        else:
            return pieces["version"] + ".dev" + str(pieces["distance"])
    elif style == "git-archival":
        # git archival style
        if pieces["distance"] is None:
            return pieces["version"]
        else:
            return pieces["version"] + ".dev" + str(pieces["distance"])
    else:
        raise ValueError("Unknown style: %s" % style)

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if not pieces:
        return "+"
    for piece in pieces:
        if piece == "+":
            return "."
    return "+"

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os
    import sys

    # If commands is a string, split it into a list
    if isinstance(commands, str):
        commands = commands.split()

    # Combine commands and args
    full_command = list(commands) + list(args)

    # Set up environment
    if env is not None:
        env = dict(os.environ)
        env.update(env)
    else:
        env = dict(os.environ)

    # Set up stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else None

    # Run the command
    try:
        if verbose:
            print(f"Running command: {' '.join(full_command)}")

        result = subprocess.run(
            full_command,
            cwd=cwd,
            env=env,
            stderr=stderr,
            stdout=subprocess.PIPE,
            text=True
        )

        if verbose:
            if result.stdout:
                print(result.stdout)
            if result.stderr and not hide_stderr:
                print(result.stderr, file=sys.stderr)

        return result.returncode

    except FileNotFoundError:
        if verbose:
            print(f"Command not found: {full_command[0]}", file=sys.stderr)
        return 127
    except Exception as e:
        if verbose:
            print(f"Error running command: {e}", file=sys.stderr)
        return 1

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Get the root object
    try:
        root = self.get_root()
    except Exception as e:
        if show_warnings:
            print(f"Warning: Could not get root object: {e}")
        return 0, 0

    # Validate the root object
    if validate_objects:
        try:
            root.validate()
            good_objects += 1
        except Exception as e:
            if show_warnings:
                print(f"Warning: Root object validation failed: {e}")
        num_objects += 1

    # Get all objects in the hierarchy
    try:
        objects = self.get_all_objects()
    except Exception as e:
        if show_warnings:
            print(f"Warning: Could not get all objects: {e}")
        return num_objects, good_objects

    # Validate each object
    for obj in objects:
        if obj is root:
            continue  # Already validated the root

        num_objects += 1

        if validate_objects:
            try:
                obj.validate()
                good_objects += 1
            except Exception as e:
                if show_warnings:
                    print(f"Warning: Object validation failed: {e}")

        if check_digests:
            try:
                obj.check_digest()
            except Exception as e:
                if show_warnings:
                    print(f"Warning: Object digest check failed: {e}")

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    # Split by dots
    parts = version.split('.')

    # Check if all parts are numeric (allowing leading zeros)
    for part in parts:
        if not part.isdigit():
            raise ValueError(f"Invalid version component: {part}")

    # Determine if the version uses zero-prefixed format
    # A version is zero-prefixed if any part has leading zeros (and length > 1)
    is_zero_prefixed = any(len(part) > 1 and part[0] == '0' for part in parts)

    # Convert to integers
    nums = [int(part) for part in parts]

    # Increment the last component
    nums[-1] += 1

    # Format back to string
    if is_zero_prefixed:
        # Preserve the original width of each part
        result_parts = []
        for i, (orig_part, num) in enumerate(zip(parts, nums)):
            width = len(orig_part)
            result_parts.append(str(num).zfill(width))
        return '.'.join(result_parts)
    else:
        return '.'.join(str(num) for num in nums)

