def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("Expected a class, got {}".format(type(cls)))

    result = set()
    for sub in cls.__subclasses__():
        result.add(sub)
        result.update(subclasses(sub))
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string:
        return 0

    # Build a mapping from character to its index in the alphabet
    char_to_index = {}
    for i, char in enumerate(alphabet):
        char_to_index[char] = i

    base = len(alphabet)
    result = 0

    for char in string:
        if char not in char_to_index:
            raise ValueError(f"Character '{char}' is not in the given alphabet")
        result = result * base + char_to_index[char]

    return result

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if len(name) >= 2 and name[0] == name[-1] and name[0] in ('"', "'"):
        return name[1:-1]
    return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        if sys.platform == 'win32':
            platform = 0
        else:
            platform = 1

    if platform == 1:
        # POSIX: use shlex.split
        try:
            return shlex.split(s)
        except ValueError:
            # If shlex fails, fall back to a simple split
            return s.split()
    elif platform == 0:
        # Windows/CMD: handle quotes and escapes
        # Windows command line parsing rules:
        # - Backslash is literal unless followed by a quote
        # - Double quotes toggle quote state
        # - Single quotes are not special
        # - Spaces and tabs separate arguments
        # - Empty arguments are not produced

        result = []
        current = []
        in_quotes = False
        i = 0
        n = len(s)

        while i < n:
            c = s[i]

            if c == '\\' and i + 1 < n and s[i+1] == '"':
                # Backslash followed by quote: literal quote
                current.append('"')
                i += 2
            elif c == '\\' and i + 1 < n and s[i+1] == '\\':
                # Backslash followed by backslash: literal backslash
                current.append('\\')
                i += 2
            elif c == '"':
                # Toggle quote state
                in_quotes = not in_quotes
                i += 1
            elif c in (' ', '\t') and not in_quotes:
                # Space or tab outside quotes: end of argument
                if current:
                    result.append(''.join(current))
                    current = []
                i += 1
            else:
                # Regular character
                current.append(c)
                i += 1

        # Add the last argument if any
        if current:
            result.append(''.join(current))

        return result
    else:
        raise ValueError(f"Invalid platform value: {platform}")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    import datetime

    import re
    if frequency is None or frequency == "always":
        return None

    if not isinstance(frequency, str):
        raise ValueError("Frequency must be a string or None")

    frequency = frequency.strip()

    # Match pattern: number followed by unit
    match = re.match(r'^(\d+)\s*(\w+)$', frequency)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    number_str, unit = match.groups()
    number = int(number_str)

    # Map unit to timedelta keyword
    unit_map = {
        'day': 'days',
        'days': 'days',
        'week': 'weeks',
        'weeks': 'weeks',
        'month': 'weeks',  # approximate: 1 month ~ 4 weeks
        'months': 'weeks',
        'year': 'weeks',   # approximate: 1 year ~ 52 weeks
        'years': 'weeks',
        'hour': 'hours',
        'hours': 'hours',
        'minute': 'minutes',
        'minutes': 'minutes',
        'second': 'seconds',
        'seconds': 'seconds',
        'millisecond': 'microseconds',  # approximate
        'milliseconds': 'microseconds',
        'microsecond': 'microseconds',
        'microseconds': 'microseconds',
    }

    unit_lower = unit.lower()

    if unit_lower in unit_map:
        kwarg = unit_map[unit_lower]
        if kwarg == 'weeks':
            if unit_lower in ('month', 'months'):
                return datetime.timedelta(weeks=number * 4)
            elif unit_lower in ('year', 'years'):
                return datetime.timedelta(weeks=number * 52)
            else:
                return datetime.timedelta(**{kwarg: number})
        elif kwarg == 'microseconds':
            if unit_lower in ('millisecond', 'milliseconds'):
                return datetime.timedelta(microseconds=number * 1000)
            else:
                return datetime.timedelta(**{kwarg: number})
        else:
            return datetime.timedelta(**{kwarg: number})
    else:
        raise ValueError(f"Unknown time unit: {unit}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    import socket
    if not host:
        return False

    # Check if host is a string
    if not isinstance(host, str):
        return False

    # Check for common localhost names
    if host.lower() in ('localhost', '127.0.0.1', '::1', '0.0.0.0'):
        return True

    # Try to resolve the hostname
    try:
        # Get all address info
        addr_info = socket.getaddrinfo(host, None)
        for family, socktype, proto, canonname, sockaddr in addr_info:
            ip = sockaddr[0]
            # Check if the IP is a loopback address
            if ip in ('127.0.0.1', '::1', '0.0.0.0'):
                return True
            # Check if it's in the 127.0.0.0/8 range
            if ip.startswith('127.'):
                return True
            # Check if it's the IPv6 loopback
            if ip == '::1':
                return True
    except socket.gaierror:
        # If we can't resolve the host, it's not local
        return False
    except Exception:
        return False

    return False

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess

    import os
    if not commands:
        raise ValueError("commands must not be empty")

    # If commands is a string, split it into a list
    if isinstance(commands, str):
        commands = commands.split()

    # If args is a string, split it into a list
    if isinstance(args, str):
        args = args.split()

    # Combine commands and args
    full_command = commands + args

    # Prepare environment
    if env is None:
        env = os.environ.copy()

    # Prepare stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else None

    # Run the command
    try:
        if verbose:
            print(f"Running command: {' '.join(full_command)}")

        process = subprocess.Popen(
            full_command,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr,
            universal_newlines=True
        )

        stdout, _ = process.communicate()

        if verbose:
            if stdout:
                print(stdout)

        return process.returncode, stdout

    except FileNotFoundError:
        raise FileNotFoundError(f"Command not found: {full_command[0]}")
    except Exception as e:
        raise Exception(f"Error running command: {e}")

