def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    try:
        # Validate shape
        if not isinstance(shape, (tuple, list)):
            raise TypeError("shape must be a tuple or list")

        # Check if all elements in shape are non-negative integers
        for dim in shape:
            if not isinstance(dim, (int, np.integer)):
                raise TypeError("All dimensions in shape must be integers")
            if dim < 0:
                raise ValueError("All dimensions in shape must be non-negative")

        # Validate dtype
        if not isinstance(dtype, np.dtype):
            try:
                dtype = np.dtype(dtype)
            except TypeError:
                raise TypeError("dtype must be a valid numpy dtype")

        # Create the array
        return np.empty(shape, dtype=dtype)

    except Exception as e:
        raise e

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol_version must be a tuple")
            if len(protocol_version) != 2:
                raise TypeError("protocol_version must be a tuple of two integers")
            if not all(isinstance(x, int) for x in protocol_version):
                raise TypeError("protocol_version must be a tuple of two integers")

        # Assume there is a class attribute or method that provides the available handlers
        # For the purpose of this implementation, we'll assume there's a class-level dictionary
        # or a method that returns the available protocol handlers.
        # Since we don't have the actual implementation details, we'll create a placeholder
        # that can be easily replaced with the actual logic.

        # In a real implementation, this would be something like:
        # available_handlers = cls._available_protocol_handlers()
        # or
        # available_handlers = cls.PROTOCOL_HANDLERS

        # For now, let's assume there's a class attribute PROTOCOL_HANDLERS
        # that maps version tuples to handler classes.

        if not hasattr(cls, 'PROTOCOL_HANDLERS'):
            # If the class doesn't have PROTOCOL_HANDLERS, return an empty dict
            # or raise an error. For robustness, let's return an empty dict.
            available_handlers = {}
        else:
            available_handlers = cls.PROTOCOL_HANDLERS

        if protocol_version is None:
            return dict(available_handlers)
        else:
            if protocol_version in available_handlers:
                return {protocol_version: available_handlers[protocol_version]}
            else:
                return {}

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, type):
        raise TypeError("iface must be a class")
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a class")

    # Check if candidate is a subclass of iface (or is iface itself)
    if not issubclass(candidate, iface):
        if tentative:
            return False
        else:
            raise TypeError(f"{candidate.__name__} is not a subclass of {iface.__name__}")

    # If tentative, just return True if it's a subclass
    if tentative:
        return True

    # For non-tentative, we might want to check that all abstract methods are implemented
    # This is a more thorough check
    try:
        # Try to instantiate to see if it's abstract
        # But we can't instantiate without arguments, so we check abstract methods
        import abc
        abstract_methods = []
        for name in dir(candidate):
            attr = getattr(candidate, name)
            if callable(attr) and getattr(attr, '__isabstractmethod__', False):
                abstract_methods.append(name)

        if abstract_methods:
            raise TypeError(f"{candidate.__name__} has unimplemented abstract methods: {', '.join(abstract_methods)}")

        return True
    except Exception as e:
        if tentative:
            return False
        else:
            raise TypeError(f"Verification failed for {candidate.__name__}: {str(e)}")

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases:
        raise ValueError("At least one base class is required")

    # If explicit metaclass is provided, use it
    if explicit_mc is not None:
        return explicit_mc

    # Find the most derived metaclass among the bases
    metaclasses = []
    for base in bases:
        if isinstance(base, type):
            metaclasses.append(type(base))
        else:
            # If base is not a class, try to get its metaclass
            try:
                metaclasses.append(type(base))
            except TypeError:
                pass

    if not metaclasses:
        return type

    # Find the most derived metaclass
    # A metaclass M1 is more derived than M2 if M1 is a subclass of M2
    most_derived = metaclasses[0]
    for mc in metaclasses[1:]:
        if issubclass(mc, most_derived):
            most_derived = mc

    return most_derived

def pop(self, key, default=__marker):
        """
        D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
        If key is not found, d is returned if given, otherwise KeyError is raised.
        """
        if key in self:
            return self.__delitem__(key)
        elif default is not __marker:
            return default
        else:
            raise KeyError(key)

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    key = next(iter(self))
    value = self[key]
    del self[key]
    return (key, value)

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        # Check if it's a public message
        if hasattr(request, 'public_message') and request.public_message:
            return 'public_message'

        # Check if it's a private message
        if hasattr(request, 'private_message') and request.private_message:
            return 'private_message'

        # Check if it's a legacy payload
        if hasattr(request, 'legacy_payload') and request.legacy_payload:
            return 'legacy_payload'

        # If none of the above, return None or a default value
        return None

    except Exception as e:
        # Handle any exceptions that might occur during identification
        return None

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Check if the request has a path that starts with /_matrix
        if hasattr(request, 'path') and request.path:
            if request.path.startswith('/_matrix'):
                return True

        # Check if the request has a host header that looks like a Matrix server
        if hasattr(request, 'headers') and request.headers:
            host = request.headers.get('Host', '')
            if host and ('matrix' in host.lower() or 'matrix.org' in host.lower()):
                return True

        # Check if the request has a user-agent that mentions Matrix
        if hasattr(request, 'headers') and request.headers:
            user_agent = request.headers.get('User-Agent', '')
            if user_agent and 'matrix' in user_agent.lower():
                return True

        return False
    except Exception:
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    if dt is None:
        raise ValueError("dt cannot be None")
    try:
        # D* nodes typically expect a specific format, e.g., "YYYY-MM-DD HH:MM:SS"
        # or possibly with microseconds. Let's use a common ISO-like format.
        # Based on common D* (D-star) implementations, they often use:
        # "%Y-%m-%d %H:%M:%S" or similar.
        # Let's assume the format is "YYYY-MM-DD HH:MM:SS"
        return dt.strftime("%Y-%m-%d %H:%M:%S")
    except (AttributeError, TypeError) as e:
        raise ValueError(f"Invalid datetime object: {e}")

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        return False
    if not tag:
        return False
    # A valid tag should:
    # 1. Start with a letter or underscore
    # 2. Contain only alphanumeric characters and underscores
    # 3. Not be empty
    # 4. Not be too long (let's say max 50 characters)
    if len(tag) > 50:
        return False
    if not (tag[0].isalpha() or tag[0] == '_'):
        return False
    for char in tag:
        if not (char.isalnum() or char == '_'):
            return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        tag = child.tag
        if tag in result:
            # If there are multiple children with the same tag, store them in a list
            if isinstance(result[tag], list):
                result[tag].append(child)
            else:
                result[tag] = [result[tag], child]
        else:
            result[tag] = child
    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json

    from typing import Dict

    from xml.etree import ElementTree
    if not document or not isinstance(document, str):
        raise ValueError("Document must be a non-empty string")

    document = document.strip()

    # Try JSON first
    if document.startswith('{'):
        try:
            data = json.loads(document)
            if not isinstance(data, dict):
                raise ValueError("JSON document must be an object")
            return data
        except json.JSONDecodeError:
            raise ValueError("Invalid JSON document")

    # Try XRD (XML)
    if document.startswith('<'):
        try:
            root = ElementTree.fromstring(document)
            result = {}

            # XRD structure: <XRD xmlns="...">
            # We need to handle namespaces
            # Common namespaces:
            # - XRD: urn:xmpp:xdg or similar
            # - Link: urn:xmpp:link or similar

            # Let's parse all elements and build a dict
            # The XRD format for webfinger typically has:
            # <XRD>
            #   <subject>acct:user@domain</subject>
            #   <alias>https://domain/user</alias>
            #   <link rel="lrdd" type="application/json" template="https://domain/.well-known/webfinger?resource={uri}"/>
            #   <link rel="http://webfinger.net/rel/profile" type="text/html" href="https://domain/user"/>
            #   <link rel="http://webfinger.net/rel/federation" type="application/activity+json" href="https://domain/activities/user"/>
            # </XRD>

            # Remove namespace for simplicity
            def strip_ns(tag):
                if '}' in tag:
                    return tag.split('}', 1)[1]
                return tag

            # Build result dict
            for child in root:
                tag = strip_ns(child.tag)
                if tag == 'subject':
                    result['subject'] = child.text
                elif tag == 'alias':
                    result['alias'] = child.text
                elif tag == 'link':
                    if 'links' not in result:
                        result['links'] = []
                    link = {}
                    for attr_name, attr_value in child.attrib.items():
                        attr_name = strip_ns(attr_name)
                        link[attr_name] = attr_value
                    result['links'].append(link)
                else:
                    # Handle other elements
                    if child.text:
                        result[tag] = child.text

            return result
        except ElementTree.ParseError:
            raise ValueError("Invalid XRD document")

    raise ValueError("Document must be in JSON or XRD format")

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import requests
    from xml.etree import ElementTree
    import re

    if not host:
        raise ValueError("Host must be provided")

    # Normalize host
    host = host.strip()
    if not host:
        raise ValueError("Host must be a non-empty string")

    # Remove protocol if present
    if host.startswith('http://') or host.startswith('https://'):
        host = re.sub(r'^https?://', '', host)

    # Remove trailing slash
    host = host.rstrip('/')

    # Try to fetch .well-known/host-meta
    url = f"https://{host}/.well-known/host-meta"

    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.exceptions.RequestException:
        # Try http if https fails
        url = f"http://{host}/.well-known/host-meta"
        try:
            response = requests.get(url, timeout=10)
            response.raise_for_status()
        except requests.exceptions.RequestException as e:
            raise Exception(f"Failed to retrieve host-meta from {host}: {e}")

    # Parse the XML response
    try:
        root = ElementTree.fromstring(response.content)
    except ElementTree.ParseError as e:
        raise Exception(f"Failed to parse host-meta XML: {e}")

    # Create a simple XRD-like object
    class XRD:
        def __init__(self, root):
            self.root = root
            self.links = []
            self.parse()

        def parse(self):
            # Handle both XRD and host-meta formats
            # XRD format: <XRD><Service><Target>...</Target><Type>...</Type></Service></XRD>
            # host-meta format: <XRD><Service><Target>...</Target><Type>...</Type></Service></XRD>

            # Find all Service elements
            for service in self.root.findall('.//{urn:xmpp:xrd:core:0.1}Service') or self.root.findall('.//Service'):
                target = service.find('{urn:xmpp:xrd:core:0.1}Target')
                if target is None:
                    target = service.find('Target')

                types = service.findall('{urn:xmpp:xrd:core:0.1}Type')
                if not types:
                    types = service.findall('Type')

                if target is not None and target.text:
                    for type_elem in types:
                        if type_elem.text:
                            self.links.append({
                                'target': target.text,
                                'type': type_elem.text
                            })

    xrd = XRD(root)
    return xrd

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    import requests
    import requests.exceptions

    try:
        # Determine the method
        method = method.lower()

        # Prepare the request
        if method == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        elif method == "get":
            response = requests.get(url, data=data, timeout=timeout, *args, **kwargs)
        elif method == "put":
            response = requests.put(url, data=data, timeout=timeout, *args, **kwargs)
        elif method == "delete":
            response = requests.delete(url, data=data, timeout=timeout, *args, **kwargs)
        elif method == "patch":
            response = requests.patch(url, data=data, timeout=timeout, *args, **kwargs)
        elif method == "head":
            response = requests.head(url, data=data, timeout=timeout, *args, **kwargs)
        elif method == "options":
            response = requests.options(url, data=data, timeout=timeout, *args, **kwargs)
        else:
            # Use the generic request method for other methods
            response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)

        return (response.status_code, None)
    except requests.exceptions.RequestException as e:
        return (None, e)
    except Exception as e:
        return (None, e)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    if not isinstance(settings_dirs, (list, tuple)):
        raise TypeError("settings_dirs must be a list or tuple")
    if not isinstance(spec_option, str):
        raise TypeError("spec_option must be a string")

    file_names = []
    for directory in settings_dirs:
        if not isinstance(directory, str):
            raise TypeError("Each element in settings_dirs must be a string")
        file_name = os.path.join(directory, spec_option)
        file_names.append(file_name)

    return file_names

