def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("spec_content is required")

        try:
            import yaml
            data = yaml.safe_load(spec_content)
        except Exception as e:
            raise IRValidatorException(f"Failed to parse YAML content: {e}")

        if not isinstance(data, dict):
            raise IRValidatorException("Spec content must be a dictionary")

        # Define required fields (example, adjust as needed)
        required_fields = ['name', 'version']

        for field in required_fields:
            if field not in data:
                raise IRValidatorException(f"Missing required field: {field}")

        return data

def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("yaml_file parameter is required")

        try:
            with open(yaml_file, 'r') as f:
                data = yaml.safe_load(f)
        except FileNotFoundError:
            raise IRValidatorException(f"File not found: {yaml_file}")
        except yaml.YAMLError as e:
            raise IRValidatorException(f"Error parsing YAML file: {e}")
        except Exception as e:
            raise IRValidatorException(f"Error reading file: {e}")

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file must contain a dictionary")

        # Validate required fields
        required_fields = ['name', 'version', 'description']
        for field in required_fields:
            if field not in data:
                raise IRValidatorException(f"Missing required field: {field}")

        return data

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """
        if not isinstance(parser_dict, dict):
            raise TypeError("parser_dict must be a dictionary")

        # Check if 'include' key exists
        if 'include' not in parser_dict:
            return parser_dict

        include_value = parser_dict['include']

        # If include is a string, treat it as a single file
        if isinstance(include_value, str):
            include_files = [include_value]
        elif isinstance(include_value, list):
            include_files = include_value
        else:
            raise ValueError("'include' must be a string or a list of strings")

        # Process each included file
        for file_path in include_files:
            if not isinstance(file_path, str):
                raise ValueError("Each include path must be a string")

            # Read the included file
            try:
                with open(file_path, 'r') as f:
                    included_content = f.read()
            except FileNotFoundError:
                raise FileNotFoundError(f"Included file not found: {file_path}")
            except IOError as e:
                raise IOError(f"Error reading included file {file_path}: {e}")

            # Parse the included content (assuming it's a dictionary representation)
            try:
                # Try to parse as a dictionary
                included_dict = eval(included_content)
                if not isinstance(included_dict, dict):
                    raise ValueError(f"Included file {file_path} must contain a dictionary")
            except Exception as e:
                raise ValueError(f"Error parsing included file {file_path}: {e}")

            # Merge the included dictionary into parser_dict
            # The included values should override existing values
            parser_dict.update(included_dict)

        # Remove the 'include' key from the result
        del parser_dict['include']

        return parser_dict

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    return self._deprecated_args

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Define deprecated arguments and their replacements
    deprecated_args = {
        'old_arg1': 'new_arg1',
        'old_arg2': 'new_arg2',
        # Add more deprecated arguments as needed
    }

    # Check for deprecated arguments in cli_args
    for arg, replacement in deprecated_args.items():
        if arg in cli_args:
            print(f"Warning: Argument '{arg}' is deprecated. Please use '{replacement}' instead.")

    # Check for deprecated arguments in answer_file_args
    for arg, replacement in deprecated_args.items():
