def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    if not hasattr(self, 'requires_args'):
        return True
    for arg in self.requires_args:
        if arg not in args:
            return False
    return True

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if hasattr(arg, 'length') and hasattr(arg, 'value'):
            if len(arg.value) > arg.length:
                raise ValueError(f"Value length {len(arg.value)} exceeds specified length {arg.length}")
        elif hasattr(arg, 'max_length') and hasattr(arg, 'value'):
            if len(arg.value) > arg.max_length:
                raise ValueError(f"Value length {len(arg.value)} exceeds specified max_length {arg.max_length}")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg in args:
        if hasattr(arg, 'choices') and arg.choices is not None:
            if arg.value not in arg.choices:
                raise ValueError(f"Value '{arg.value}' is not one of the available choices: {arg.choices}")

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        if not isinstance(args, dict):
            raise TypeError("args must be a dictionary")

        for key, value in args.items():
            if key not in self.min_max:
                continue
            min_val, max_val = self.min_max[key]
            if not isinstance(value, (int, float)):
                raise ValueError(f"Value for '{key}' must be a number")
            if value < min_val or value > max_val:
                raise ValueError(f"Value for '{key}' must be between {min_val} and {max_val}")

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if extra_vars is None:
            return vars_dict

        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")

        if not isinstance(extra_vars, (list, tuple)):
            raise TypeError("extra_vars must be a list or tuple")

        for item in extra_vars:
            if not isinstance(item, str):
                raise TypeError("Each item in extra_vars must be a string")

            if '=' not in item:
                raise ValueError(f"Invalid extra-var format: {item}. Expected 'key=value'")

            key, value = item.split('=', 1)
            key = key.strip()
            value = value.strip()

            if not key:
                raise ValueError(f"Empty key in extra-var: {item}")

            vars_dict[key] = value

        return vars_dict

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    import subprocess
    import json
    import os
    import tempfile

    # Validate inputs
    if not isinstance(cli_args, list):
        raise TypeError("cli_args must be a list")
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")
    if ir_workspace is None:
        raise ValueError("ir_workspace cannot be None")
    if ir_plugin is None:
        raise ValueError("ir_plugin cannot be None")

    # Build the command
    cmd = ["ansible-playbook"]

    # Add extra vars
    if vars_dict:
        # Create a temporary file for the vars
        with tempfile.NamedTemporaryFile(mode='w', suffix='.json', delete=False) as f:
            json.dump(vars_dict, f)
            vars_file = f.name
        cmd.extend(["-e", f"@{vars_file}"])

    # Add the rest of the CLI args
    cmd.extend(cli_args)

    # Set up environment
    env = os.environ.copy()

    # Try to get workspace path if available
    try:
        workspace_path = getattr(ir_workspace, 'path', None) or getattr(ir_workspace, 'workspace_path', None)
        if workspace_path:
            env['ANSIBLE_INVENTORY'] = os.path.join(workspace_path, 'inventory')
            env['ANSIBLE_ROLES_PATH'] = os.path.join(workspace_path, 'roles')
            env['ANSIBLE_PLAYBOOKS_PATH'] = os.path.join(workspace_path, 'playbooks')
    except Exception:
        pass

    # Try to get plugin specific environment variables
    try:
        plugin_env = getattr(ir_plugin, 'get_environment', lambda: {})()
        if isinstance(plugin_env, dict):
            env.update(plugin_env)
    except Exception:
        pass

    try:
        # Run the command
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            env=env,
            timeout=3600  # 1 hour timeout
        )

        # Parse the output
        stdout = result.stdout
        stderr = result.stderr
        return_code = result.returncode

        # Try to parse JSON output if available
        ansible_results = {}
        try:
            # Look for JSON in stdout
            if stdout:
                # Try to find JSON object in the output
                json_start = stdout.find('{')
                if json_start != -1:
                    json_str = stdout[json_start:]
                    # Find the matching closing brace
                    brace_count = 0
                    for i, char in enumerate(json_str):
                        if char == '{':
                            brace_count += 1
                        elif char == '}':
                            brace_count -= 1
                            if brace_count == 0:
                                json_str = json_str[:i+1]
                                break
                    ansible_results = json.loads(json_str)
        except Exception:
            # If JSON parsing fails, return raw output
            ansible_results = {
                'stdout': stdout,
                'stderr': stderr,
                'return_code': return_code
            }

        # Add metadata
        ansible_results['return_code'] = return_code
        if stderr:
            ansible_results['stderr'] = stderr

        return ansible_results

    except subprocess.TimeoutExpired:
        return {
            'error': 'Command timed out',
            'return_code': -1
        }
    except Exception as e:
        return {
            'error': str(e),
            'return_code': -1
        }
    finally:
        # Clean up temporary file
        if 'vars_file' in locals() and os.path.exists(vars_file):
            try:
                os.unlink(vars_file)
            except Exception:
                pass

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
       """
        if not isinstance(values_dict, dict):
            raise TypeError("values_dict must be a dictionary")

        # Define a mapping of argument names to their expected types
        # This is a simplified example; in a real scenario, this would be
        # more comprehensive and possibly data-driven
        type_mapping = {
            'port': int,
            'timeout': int,
            'retries': int,
            'verbose': bool,
            'debug': bool,
            'dry_run': bool,
            'max_connections': int,
            'buffer_size': int,
            'rate_limit': float,
            'threshold': float,
        }

        # Convert values based on the type mapping
        for key, value in values_dict.items():
            if key in type_mapping:
                target_type = type_mapping[key]
                try:
                    if target_type is bool:
                        # Handle boolean conversion specially
                        if isinstance(value, str):
                            value_lower = value.lower()
                            if value_lower in ('true', '1', 'yes', 'on'):
                                values_dict[key] = True
                            elif value_lower in ('false', '0', 'no', 'off'):
                                values_dict[key] = False
                            else:
                                # If it's not a recognizable boolean string, keep as is or raise
                                values_dict[key] = bool(value)
                        else:
                            values_dict[key] = bool(value)
                    else:
                        values_dict[key] = target_type(value)
                except (ValueError, TypeError):
                    # If conversion fails, leave the value as is or handle appropriately
                    # For robustness, we might want to log this or raise a specific error
                    pass

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    import yaml

    # Validate input
    if not isinstance(plugin_dir, str):
        raise TypeError("plugin_dir must be a string")

    if not os.path.exists(plugin_dir):
        raise FileNotFoundError(f"Plugin directory does not exist: {plugin_dir}")

    if not os.path.isdir(plugin_dir):
        raise NotADirectoryError(f"Path is not a directory: {plugin_dir}")

    # Look for plugin spec file
    spec_file = None
    for filename in ['plugin.json', 'plugin.yaml', 'plugin.yml', 'spec.json', 'spec.yaml', 'spec.yml']:
        filepath = os.path.join(plugin_dir, filename)
        if os.path.exists(filepath):
            spec_file = filepath
            break

    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Load the spec file
    try:
        with open(spec_file, 'r', encoding='utf-8') as f:
            if spec_file.endswith('.json'):
                spec_data = json.load(f)
            else:
                spec_data = yaml.safe_load(f)
    except Exception as e:
        raise ValueError(f"Failed to parse plugin spec file: {e}")

    if not isinstance(spec_data, dict):
        raise ValueError("Plugin spec must be a dictionary")

    # Flatten the dictionary
    def flatten_dict(d, parent_key='', sep='.'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            elif isinstance(v, list):
                # For lists, we can either keep them as is or flatten them
                # Let's keep them as is for simplicity, but if they contain dicts, flatten those
                if all(isinstance(item, dict) for item in v):
                    for i, item in enumerate(v):
                        items.extend(flatten_dict(item, f"{new_key}[{i}]", sep=sep).items())
                else:
                    items.append((new_key, v))
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(spec_data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    if 'CONFIG_PATH' not in os.environ:
        # Set a default config path if not already defined
        os.environ['CONFIG_PATH'] = 'config.json'
